 check(roomWalk.outside.n<2938&&roomWalk.inside.n>2943,'Classroom entrance can be exited and re-entered on foot: '+JSON.stringify(roomWalk));
 check(roomWalk.window.e<1470.65&&roomWalk.window.e>1469,'Classroom windows block walking through the exterior wall: '+JSON.stringify(roomWalk));
 check(roomWalk.desk.n<2946.4&&roomWalk.retreat.n<roomWalk.desk.n-1,'Classroom desks/chairs block movement and allow retreat: '+JSON.stringify(roomWalk));
