 check(await evaluate(`tr.state.mapLocation==='surface'&&tr.state.surface===tr.scene.tableAnchors.findIndex(a=>a.parent.name==='classroom-map-table')&&tr.state.mode==='map'`),'Classroom workbench supports the actual carried map');await screenshot('classroom-map-workbench');
