 const picnicWalk=await evaluate(`(()=>{const saved={player:{...tr.state.player},north:tr.state.north,yaw:tr.state.yaw,paused:tr.state.paused,mode:tr.state.mode};tr.state.north=0;tr.state.yaw=0;tr.state.mode='explore';tr.state.paused=false;tr.state.player={e:1959,n:1654};tr.scene.render(false);tr.scene.keys.add('KeyW');for(let i=0;i<100;i++)tr.scene.step(.05);const stopped={...tr.state.player};tr.scene.keys.clear();tr.scene.keys.add('KeyS');for(let i=0;i<20;i++)tr.scene.step(.05);const retreat={...tr.state.player};tr.scene.keys.clear();tr.state.player={e:1959,n:1658};tr.scene.keys.add('KeyS');for(let i=0;i<20;i++)tr.scene.step(.05);const recovered={...tr.state.player};tr.scene.keys.clear();Object.assign(tr.state,saved);tr.scene.render(false);return {stopped,retreat,recovered};})()`);
 check(picnicWalk.stopped.n<1656.70,'Bench blocks walking through furniture: '+JSON.stringify(picnicWalk));
