 console.log('State',await evaluate(`({normals:Array.from(tr.scene.terrain.getVerticesData(BABYLON.VertexBuffer.NormalKind)).slice(0,6),textures:tr.scene.scene.textures.filter(t=>t.url).map(t=>t.url.slice(0,140)),player:tr.state.player,mode:tr.state.mode,paused:tr.state.paused,meshes:tr.scene.scene.meshes.length,fps:tr.scene.engine.getFps(),errors:fpErrors,csp:fpCSP})`));
