 await key('Escape','Escape');check(await evaluate(`tr.state.mode==='map'&&tr.state.notepadLocation==='stowed'&&tr.state.handTool===${JSON.stringify(notesOverlayBefore.tool)}&&tr.state.activeSlot===${notesOverlayBefore.slot}&&!document.pointerLockElement`),'Closing notebook restores free-cursor map editing and prior inventory');
 const navigationBefore=await evaluate(`({yaw:tr.state.yaw,paper:tr.state.paperAngle,ring:tr.state.compass.ring,player:{...tr.state.player}})`);
 await send('Input.dispatchKeyEvent',{type:'keyDown',code:'KeyD',key:'d'},sessionId);await evaluate(`tr.scene.step(.05)`);await send('Input.dispatchKeyEvent',{type:'keyUp',code:'KeyD',key:'d'},sessionId);
 check(await evaluate(`tr.state.mode==='map'&&tr.state.yaw!==${navigationBefore.yaw}&&Math.abs((tr.state.paperAngle-${navigationBefore.paper})-(tr.state.yaw-${navigationBefore.yaw}))<.01&&tr.state.compass.ring===${navigationBefore.ring}`),'A/D rotate body and held map together in F mode');
 await send('Input.dispatchKeyEvent',{type:'keyDown',code:'KeyW',key:'w'},sessionId);await evaluate(`tr.scene.step(.05)`);await send('Input.dispatchKeyEvent',{type:'keyUp',code:'KeyW',key:'w'},sessionId);
 check(await evaluate(`Math.hypot(tr.state.player.e-${navigationBefore.player.e},tr.state.player.n-${navigationBefore.player.n})>.01&&!document.pointerLockElement`),'W/S walk in F mode with free cursor: '+JSON.stringify(await evaluate(`({mode:tr.state.mode,paused:tr.state.paused,player:tr.state.player,lock:document.pointerLockElement?.id,keys:[...tr.scene.keys]})`)));
