 check(await evaluate(`tr.state.mode==='map'&&tr.state.yaw!==${yawBeforeLook}`),'Right drag looks around while editing map');await key('Escape','Escape');console.log('Map-mode walking, body rotation and mouse look passed');
 await new Promise(r=>setTimeout(r,200));await evaluate(`document.getElementById('fpJournalOpen').click()`);await new Promise(r=>setTimeout(r,100));await key('Escape','Escape');await new Promise(r=>setTimeout(r,150));check(await evaluate(`tr.state.mode==='explore'&&!tr.state.paused&&document.pointerLockElement===document.getElementById('fpCanvas')`),'Escape closes journal and automatically recaptures the mouse: '+JSON.stringify(await evaluate(`({mode:tr.state.mode,paused:tr.state.paused,lock:document.pointerLockElement?.id,toast:document.getElementById('fpToast').textContent,focus:document.activeElement?.id})`)));
 await evaluate(`tr.state.mapLocation='hand';tr.state.notepadLocation='stowed';tr.state.items.pencil='stowed';tr.state.handTool=null;tr.state.items.romer='stowed';tr.state.items.compass='stowed';tr.state.mode='explore';tr.state.paused=false;tr.scene.render(false);document.getElementById('fpCanvas').focus()`);
 const rect=await evaluate(`(()=>{const r=document.getElementById('fpCanvas').getBoundingClientRect();return {x:r.x+r.width*.6,y:r.y+r.height*.45};})()`);
