 await evaluate(`tr.state.handTool='compass';tr.state.items.compass='hand'`);await right('mousePressed');check(await evaluate(`tr.state.mode==='sight'`),'Right mouse holds compass sight');check(await evaluate(`document.getElementById('fpCrosshair').hidden`),'No artificial sighting crosshair');
 const compassClear=await evaluate(`(()=>{tr.scene.render(false);const c=tr.scene.compassPlate;c.computeWorldMatrix(true);const r=document.getElementById('fpCanvas').getBoundingClientRect(),h=tr.scene.engine.getRenderHeight(),w=tr.scene.engine.getRenderWidth(),viewport=tr.scene.camera.viewport.toGlobal(w,h);const points=c.getBoundingInfo().boundingBox.vectorsWorld.map(p=>BABYLON.Vector3.Project(p,BABYLON.Matrix.Identity(),tr.scene.scene.getTransformMatrix(),viewport));const inv=document.getElementById('fpInventory').getBoundingClientRect();return {fov:tr.scene.camera.fov,left:Math.min(...points.map(p=>p.x/w*r.width+r.left)),right:Math.max(...points.map(p=>p.x/w*r.width+r.left)),top:Math.min(...points.map(p=>p.y/h*r.height+r.top)),bottom:Math.max(...points.map(p=>p.y/h*r.height+r.top)),inventory:{left:inv.left,right:inv.right,top:inv.top,bottom:inv.bottom}};})()`);check(compassClear.fov===1.02,'Compass sight retains normal field of view');const inv=compassClear.inventory;check(compassClear.right<inv.left-12||compassClear.left>inv.right+12||compassClear.bottom<inv.top-12||compassClear.top>inv.bottom+12,'Sighting compass clears inventory: '+JSON.stringify(compassClear));
