 await evaluate(`tr.state.player={e:1959,n:1655};tr.state.yaw=0;tr.state.pitch=12;tr.scene.render()`);await screenshot('picnic-area');await evaluate(`tr.state.player={e:1959,n:1656.1};tr.scene.render(false)`);await key('KeyE','e');await evaluate(`document.getElementById('fpAttach').click()`);await new Promise(r=>setTimeout(r,150));
